"""The page is generated by htpy; there is no HTML file on disk."""

import pathlib

import pytest

PANELS = ("brief", "stack", "shell", "files", "kanban", "progress", "docs", "logs")


def test_page_serves_every_panel(client):
    body = client.get("/").data.decode()
    assert body.lower().startswith("<!doctype html>")
    for panel in PANELS:
        assert f'data-tabpanel="{panel}"' in body
    for element_id in (
        "kanban-view",
        "docs-view",
        "logs-view",
        "progress-view",
        "files-view",
        "brief",
        "shell-view",
        "stack-view",
        "kanban-board",
        "docs-editor",
        "progress-dialog",
        "kbd-title",
    ):
        assert f'id="{element_id}"' in body
    assert 'src="/static/js/main.js?v=' in body


def test_page_keeps_alpine_scopes(client):
    body = client.get("/").data.decode()
    assert 'x-data="chrome"' in body
    # Unmounted views stay out of the chrome scope until the router mounts them.
    assert body.count("x-ignore") >= len(PANELS)


def test_no_html_files_ship():
    html = [p for p in pathlib.Path("static").rglob("*.html")]
    assert html == []


def test_index_alias_serves_the_same_page(client):
    assert client.get("/").data == client.get("/index.html").data


@pytest.mark.parametrize(
    "asset", ["/static/css/tui.css", "/static/js/alpine.js", "/static/vendor/alpine-3.14.9.esm.js"]
)
def test_assets_still_served(client, asset):
    assert client.get(asset).status_code == 200
